<?php
session_start();
$_SESSION['checkout_csrf']??=bin2hex(random_bytes(32));
if(!file_exists(__DIR__.'/config.php')){http_response_code(503);exit('Configure config.php first.');}
$c=require __DIR__.'/config.php';
try{$db=new PDO('mysql:host='.$c['host'].';dbname='.$c['database'].';charset=utf8mb4',$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}catch(PDOException $e){http_response_code(503);exit('Database unavailable.');}
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
$_SESSION['cart']??=[];
if($_SERVER['REQUEST_METHOD']==='POST' && !hash_equals($_SESSION['checkout_csrf'],(string)($_POST['csrf']??''))){http_response_code(403);exit('Invalid request token.');}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['remove'])){unset($_SESSION['cart'][(int)$_POST['remove']]);header('Location: cart.php');exit;}
$ids=array_keys($_SESSION['cart']);$items=[];$total=0;
if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$q=$db->prepare("SELECT id,name,price FROM products WHERE is_available=1 AND id IN ($marks)");$q->execute($ids);foreach($q as $p){$p['quantity']=(int)$_SESSION['cart'][$p['id']];$p['subtotal']=$p['quantity']*$p['price'];$total+=$p['subtotal'];$items[]=$p;}}
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['checkout'])){
$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$method=$_POST['fulfillment']??'';$address=trim($_POST['address']??'');
if(!$items || !$name || !filter_var($email,FILTER_VALIDATE_EMAIL) || !$phone || !in_array($method,['pickup','delivery'],true) || ($method==='delivery' && !$address)){$error='Please complete all required fields and ensure your cart has available products.';}
else{try{$db->beginTransaction();$q=$db->prepare('INSERT INTO orders(customer_id,customer_name,email,phone,fulfillment,delivery_address,total) VALUES(?,?,?,?,?,?,?)');$q->execute([$_SESSION['customer_id']??null,$name,$email,$phone,$method,$method==='delivery'?$address:null,$total]);$orderId=$db->lastInsertId();$q=$db->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');foreach($items as $p){$q->execute([$orderId,$p['id'],$p['quantity'],$p['price']]);}$db->commit();$_SESSION['cart']=[];$items=[];$success='Order #'.$orderId.' received. This prototype does not process online payments.';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error='Could not submit your order. Please try again.';}}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cart | The Yummy House</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="top"><a class="brand" href="index.php">The Yummy House</a><nav class="nav"><a href="index.php#menu">Continue shopping</a></nav></header><main class="container"><div class="panel"><h1>Your order</h1><p><a href="customer/login.php">Sign in</a> to save orders to your account.</p><?php if($error):?><p role="alert"><?=h($error)?></p><?php endif;?><?php if($success):?><p role="status"><?=h($success)?></p><?php endif;?><?php foreach($items as $p):?><div class="row"><p><?=h($p['name'])?> × <?= $p['quantity'] ?></p><div><strong>R<?=number_format($p['subtotal'],2)?></strong> <form method="post" style="display:inline"><button name="remove" value="<?=$p['id']?>" type="submit">Remove</button></form></div></div><?php endforeach;?><hr><div class="row"><strong>Total (excludes any delivery charge)</strong><strong>R<?=number_format($total,2)?></strong></div><?php if($items):?><h2>Checkout</h2><p class="muted">Prototype order request only. The restaurant must confirm availability and any delivery fee before payment.</p><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['checkout_csrf'])?>"><label for="name">Full name</label><input id="name" name="name" required maxlength="150"><label for="email">Email</label><input id="email" name="email" type="email" required><label for="phone">Phone</label><input id="phone" name="phone" required maxlength="30"><label for="fulfillment">Order method</label><select id="fulfillment" name="fulfillment" required><option value="pickup">Pickup</option><option value="delivery">Delivery</option></select><label for="address">Delivery address (required for delivery)</label><textarea id="address" name="address" rows="3"></textarea><p><button name="checkout" value="1" type="submit">Place order request</button></p></form><?php elseif(!$success):?><p class="muted">Your cart is empty.</p><?php endif;?></div></main><footer>Yummy House coursework prototype</footer></body></html>
